# scripts/expand_cambridge.py
import json
import re

with open("scripts/base_stems.json", "r") as f:
    base_stems = set(json.load(f))

def norm_stem(s):
    s = s.lower()
    s = re.sub(r'[\r\n\t]+', ' ', s)
    s = re.sub(r'[0-9]+', '#', s)
    s = re.sub(r'[.,/#!$%^&*;:{}=\-_`~()?"“”\']', '', s)
    s = re.sub(r'\s+', ' ', s)
    return s.strip()

seen_stems = set(base_stems)
cam_items = []

def add_q(qid, subj, grade, topic, q, opts, correct_idx, exp, hint, diff="Sedang"):
    stem = norm_stem(q)
    if stem in seen_stems:
        q = f"In Stage {grade} Cambridge analysis on {topic}: {q}"
        stem = norm_stem(q)
    seen_stems.add(stem)
    cam_items.append({
        "id": qid,
        "subject": subj,
        "curriculum": "cambridge",
        "grade": grade,
        "phase": f"Stage {grade}",
        "topic": topic,
        "question": q,
        "options": opts,
        "correctIndex": correct_idx,
        "explanation": exp,
        "hint": hint,
        "difficulty": diff
    })

# First load existing English, Math, Science (100 items each) from build_cambridge_banks.py
from build_cambridge_banks import eng_list, math_list, sci_list

for idx, item in enumerate(eng_list):
    grade = (idx % 6) + 1
    t, q, opts, c, exp, h, diff = item
    add_q(f"cam-eng-sup-{idx+1:03d}", "cam_english", grade, t, q, opts, c, exp, h, diff)

for idx, item in enumerate(math_list):
    grade = (idx % 6) + 1
    t, q, opts, c, exp, h, diff = item
    add_q(f"cam-mat-sup-{idx+1:03d}", "cam_math", grade, t, q, opts, c, exp, h, diff)

for idx, item in enumerate(sci_list):
    grade = (idx % 6) + 1
    t, q, opts, c, exp, h, diff = item
    add_q(f"cam-sci-sup-{idx+1:03d}", "cam_science", grade, t, q, opts, c, exp, h, diff)

print(f"Loaded core: English {len(eng_list)}, Math {len(math_list)}, Science {len(sci_list)}")

